INSERT INTO `plantillas_comunicacion` VALUES (1,'Comunicación de sugerencias ciudadanas','Traslado de sugerencias ciudadanas en {{provincia}}','A la atención de {{institucion}}: Desde CityPAJ se han recibido {{numero_sugerencias}} sugerencias ciudadanas.','Plantilla institucional','institucional',1,0,NULL,'305eff30-ea27-4511-a2a8-774b236d22c8','2026-08-02 14:03:33','2026-08-02 14:03:33'),(2,'Aviso de necesidad juvenil','Aviso: necesidad juvenil repetida en {{provincia}}','Se ha identificado una necesidad juvenil que aparece de forma reiterada: {{tema_principal}}.','Plantilla de aviso','institucional',1,0,NULL,'305eff30-ea27-4511-a2a8-774b236d22c8','2026-08-02 14:03:33','2026-08-02 14:03:33'),(3,'Resumen mensual','Resumen mensual de participación juvenil — {{provincia}}','Se adjunta el resumen mensual de actividad registrada en CityPAJ.','Plantilla de resumen','institucional',1,0,NULL,'305eff30-ea27-4511-a2a8-774b236d22c8','2026-08-02 14:03:33','2026-08-02 14:03:33'),(4,'Comunicación de sugerencias ciudadanas','Traslado de sugerencias ciudadanas en {{provincia}}','A la atención de {{institucion}}:\n\nDesde CityPAJ se han recibido {{numero_sugerencias}} sugerencias ciudadanas relacionadas con {{tema_principal}} en la provincia de {{provincia}}.\n\nSe adjunta un resumen de las aportaciones recibidas para su conocimiento y posible valoración por el área competente.\n\nLa información trasladada procede de publicaciones, sugerencias y propuestas registradas en la plataforma, y tiene como finalidad facilitar una lectura territorial de las necesidades expresadas por la población joven.\n\nQuedamos a disposición para ampliar la información o colaborar en futuras vías de participación.\n\nAtentamente,\n\n{{nombre_admin}}\nEquipo CityPAJ','Plantilla predefinida: Comunicación de sugerencias ciudadanas','institucional',1,0,NULL,'fe7f7831-c764-4c50-bdcf-157438a78ef6','2026-08-02 14:57:09','2026-08-02 14:57:09'),(5,'Traslado de propuesta comunitaria','Propuesta comunitaria: {{titulo_propuesta}}','A la atención de {{institucion}}:\n\nDesde CityPAJ se nos ha trasladado una propuesta comunitaria titulada \"{{titulo_propuesta}}\", con {{numero_apoyos}} apoyos registrados, relacionada con {{tema_principal}} en {{provincia}}.\n\nResumen:\n{{resumen_propuestas}}\n\nAgradecemos la consideración de esta iniciativa y quedamos a disposición para facilitar información adicional o colaborar en su difusión.\n\nAtentamente,\n\n{{nombre_admin}}\nEquipo CityPAJ','Plantilla predefinida: Traslado de propuesta comunitaria','institucional',1,0,NULL,'fe7f7831-c764-4c50-bdcf-157438a78ef6','2026-08-02 14:57:09','2026-08-02 14:57:09'),(6,'Informe de situación detectada','Informe de situación detectada en {{provincia}}','A la atención de {{institucion}}:\n\nEl equipo de CityPAJ ha detectado una situación de interés relativa a {{tema_principal}} en la provincia de {{provincia}}.\n\nDescripción del hallazgo:\n{{resumen_sugerencias}}\n\nSe adjunta la información disponible para su conocimiento.\n\nAtentamente,\n\n{{nombre_admin}}\nEquipo CityPAJ','Plantilla predefinida: Informe de situación detectada','institucional',1,0,NULL,'fe7f7831-c764-4c50-bdcf-157438a78ef6','2026-08-02 14:57:09','2026-08-02 14:57:09'),(7,'Aviso de necesidad juvenil repetida','Aviso: necesidad juvenil repetida en {{provincia}}','A la atención de {{institucion}}:\n\nSe ha identificado una necesidad juvenil que aparece de forma reiterada en la plataforma CityPAJ: {{tema_principal}} en {{provincia}}.\n\nNúmero de sugerencias vinculadas: {{numero_sugerencias}}.\n\nSe adjunta un resumen de las aportaciones para su análisis.\n\nAtentamente,\n\n{{nombre_admin}}\nEquipo CityPAJ','Plantilla predefinida: Aviso de necesidad juvenil repetida','institucional',1,0,NULL,'fe7f7831-c764-4c50-bdcf-157438a78ef6','2026-08-02 14:57:09','2026-08-02 14:57:09'),(8,'Solicitud de colaboración institucional','Solicitud de colaboración con {{institucion}}','A la atención de {{institucion}}:\n\nDesde CityPAJ nos ponemos en contacto para explorar vías de colaboración en materia de {{tema_principal}} en {{provincia}}.\n\nConcretamente, nos interesa coordinar actuaciones relacionadas con las necesidades juveniles detectadas a través de la plataforma.\n\nQuedamos a la espera de su respuesta para programar una reunión o intercambio de información.\n\nAtentamente,\n\n{{nombre_admin}}\nEquipo CityPAJ','Plantilla predefinida: Solicitud de colaboración institucional','institucional',1,0,NULL,'fe7f7831-c764-4c50-bdcf-157438a78ef6','2026-08-02 14:57:09','2026-08-02 14:57:09'),(9,'Resumen mensual por provincia','Resumen mensual de participación juvenil — {{provincia}}','A la atención de {{institucion}}:\n\nSe adjunta el resumen mensual de actividad registrada en CityPAJ para la provincia de {{provincia}}.\n\nSugerencias recibidas: {{numero_sugerencias}}\nPropuestas comunitarias: {{resumen_propuestas}}\nTema principal: {{tema_principal}}\n\nAtentamente,\n\n{{nombre_admin}}\nEquipo CityPAJ','Plantilla predefinida: Resumen mensual por provincia','institucional',1,0,NULL,'fe7f7831-c764-4c50-bdcf-157438a78ef6','2026-08-02 14:57:09','2026-08-02 14:57:09'),(10,'Comunicación urgente por contenido sensible','URGENTE: Contenido sensible en {{provincia}}','A la atención de {{institucion}}:\n\nSe ha detectado en CityPAJ contenido o una situación relevante que requiere atención inmediata en {{provincia}}.\n\nDetalles:\n{{resumen_sugerencias}}\n\nSe ha marcado con prioridad alta. Rogamos contacto urgente para valorar la actuación necesaria.\n\nAtentamente,\n\n{{nombre_admin}}\nEquipo CityPAJ','Plantilla predefinida: Comunicación urgente por contenido sensible','institucional',1,0,NULL,'fe7f7831-c764-4c50-bdcf-157438a78ef6','2026-08-02 14:57:09','2026-08-02 14:57:09'),(11,'Comunicación de sugerencias ciudadanas','Traslado de sugerencias ciudadanas en {{provincia}}','A la atención de {{institucion}}:\n\nDesde CityPAJ se han recibido {{numero_sugerencias}} sugerencias ciudadanas relacionadas con {{tema_principal}} en la provincia de {{provincia}}.\n\nSe adjunta un resumen de las aportaciones recibidas para su conocimiento y posible valoración por el área competente.\n\nLa información trasladada procede de publicaciones, sugerencias y propuestas registradas en la plataforma, y tiene como finalidad facilitar una lectura territorial de las necesidades expresadas por la población joven.\n\nQuedamos a disposición para ampliar la información o colaborar en futuras vías de participación.\n\nAtentamente,\n\n{{nombre_admin}}\nEquipo CityPAJ','Plantilla predefinida: Comunicación de sugerencias ciudadanas','institucional',1,0,NULL,'802a0956-485e-4c2e-bbc8-e4236da1c6b8','2026-08-02 16:15:21','2026-08-02 16:15:21'),(12,'Traslado de propuesta comunitaria','Propuesta comunitaria: {{titulo_propuesta}}','A la atención de {{institucion}}:\n\nDesde CityPAJ se nos ha trasladado una propuesta comunitaria titulada \"{{titulo_propuesta}}\", con {{numero_apoyos}} apoyos registrados, relacionada con {{tema_principal}} en {{provincia}}.\n\nResumen:\n{{resumen_propuestas}}\n\nAgradecemos la consideración de esta iniciativa y quedamos a disposición para facilitar información adicional o colaborar en su difusión.\n\nAtentamente,\n\n{{nombre_admin}}\nEquipo CityPAJ','Plantilla predefinida: Traslado de propuesta comunitaria','institucional',1,0,NULL,'802a0956-485e-4c2e-bbc8-e4236da1c6b8','2026-08-02 16:15:21','2026-08-02 16:15:21'),(13,'Informe de situación detectada','Informe de situación detectada en {{provincia}}','A la atención de {{institucion}}:\n\nEl equipo de CityPAJ ha detectado una situación de interés relativa a {{tema_principal}} en la provincia de {{provincia}}.\n\nDescripción del hallazgo:\n{{resumen_sugerencias}}\n\nSe adjunta la información disponible para su conocimiento.\n\nAtentamente,\n\n{{nombre_admin}}\nEquipo CityPAJ','Plantilla predefinida: Informe de situación detectada','institucional',1,0,NULL,'802a0956-485e-4c2e-bbc8-e4236da1c6b8','2026-08-02 16:15:21','2026-08-02 16:15:21'),(14