INSERT INTO `sugerencias` VALUES (1,'María García','maria@email.com','19-22','educacion','alta','Más espacios de estudio gratuitos','Necesitamos más bibliotecas y espacios de estudio gratuitos en la zona universitaria, especialmente en horarios nocturnos para estudiantes que trabajan durante el día.','Solicito la habilitación de espacios municipales como centros cívicos para uso como salas de estudio 24/7 durante épocas de exámenes.',0,'Madrid','2024-01-15 10:30:00','pendiente',1,'2026-08-02 10:46:53','04873d27-5aab-11f1-a334-5811223fa053',NULL),(2,'Juan López',NULL,'23-25','empleo','critica','Programa de prácticas remuneradas','No hay suficientes oportunidades de prácticas para jóvenes sin experiencia. Las empresas no quieren contratar sin experiencia y no podemos conseguir experiencia sin prácticas.','Solicito la creación de un programa municipal de subvenciones para empresas que ofrezcan prácticas remuneradas a jóvenes de la comunidad.',1,'Cataluña','2024-01-14 15:45:00','en_progreso',0,NULL,NULL,NULL),(3,'Ana Martínez','ana@email.com','16-18','deportes','media','Instalaciones deportivas gratuitas','Los precios de las pistas deportivas municipales son muy altos para jóvenes. Debería haber tarifas juveniles más accesibles.','Solicito la implementación de un carnet joven deportivo con acceso gratuito a instalaciones municipales los fines de semana.',0,'Andalucía','2024-01-13 09:20:00','revisada',0,NULL,NULL,NULL),(4,NULL,NULL,NULL,'transporte','alta','Transporte nocturno juvenil','No hay transporte público nocturno y los jóvenes no pueden volver a casa después de eventos culturales o trabajos nocturnos.','Solicito la creación de líneas de autobús nocturnas con tarifas especiales para jóvenes los viernes y sábados.',1,'País Vasco','2024-01-12 22:10:00','pendiente',0,NULL,NULL,NULL),(5,'Carlos Ruiz','carlos@email.com','26-30','vivienda','critica','Alquiler juvenil asequible','Los precios del alquiler son imposibles para jóvenes con salarios iniciales. Necesitamos programas de vivienda juvenil.','Solicito la creación de un programa de viviendas de alquiler a precios reducidos para jóvenes de 18 a 30 años con ingresos limitados.',0,'Comunidad Valenciana','2024-01-11 14:30:00','pendiente',0,NULL,NULL,NULL),(6486,'Test User','test@example.com',NULL,'educacion','media','Test Sugerencia','Esta es una sugerencia de prueba',NULL,0,'Madrid','2026-06-02 17:35:05','pendiente',0,NULL,NULL,NULL),(29329,'Test User','test@example.com',NULL,'educacion','media','Test Sugerencia','Esta es una sugerencia de prueba',NULL,0,'Madrid','2026-06-01 15:42:13','pendiente',0,NULL,NULL,NULL),(42668,'Test User','test@example.com',NULL,'educacion','media','Test Sugerencia','Esta es una sugerencia de prueba',NULL,0,'Madrid','2026-06-01 11:57:27','pendiente',0,NULL,NULL,NULL),(42669,'Test User','test@example.com',NULL,'educacion','media','Test Sugerencia','Esta es una sugerencia de prueba',NULL,0,'Madrid','2026-06-02 17:33:04','pendiente',0,NULL,NULL,NULL),(42670,'Ciudadano 0','sug0@example.com','18','transporte','alta','Más autobuses nocturnos','Necesitamos más frecuencias los fines de semana.',NULL,0,'Aragón','2026-08-02 00:00:00','pendiente',0,NULL,NULL,'127.0.0.1'),(42671,'Ciudadano 1','sug1@example.com','19','','media','Conciertos gratuitos','Propuesta de conciertos en parques.',NULL,1,'Aragón','2026-08-01 00:00:00','revisada',0,NULL,NULL,'127.0.0.1'),(42672,'Ciudadano 2','sug2@example.com','20','empleo','alta','App de empleo','Un buscador de ofertas para jóvenes.',NULL,0,'Aragón','2026-07-31 00:00:00','en_progreso',0,NULL,NULL,'127.0.0.1'),(42673,'Ciudadano 3','sug3@example.com','21','vivienda','','Vivienda compartida','Cooperativas de vivienda juvenil.',NULL,1,'Aragón','2026-07-30 00:00:00','resuelta',0,NULL,NULL,'127.0.0.1'),(42674,'Ciudadano 4','sug4@example.com','22','','media','Talleres de salud mental','Grupos de apoyo para jóvenes.',NULL,0,'Aragón','2026-07-29 00:00:00','rechazada',0,NULL,NULL,'127.0.0.1'),(42675,'Ciudadano 5','sug5@example.com','23','ocio','baja','Zonas wifi gratuitas','Más puntos de acceso en barrios.',NULL,1,'Aragón','2026-07-28 00:00:00','pendiente',0,NULL,NULL,'127.0.0.1'),(42676,'Ciudadano 6','sug6@example.com','24','','media','Becas deporte','Ayudas para actividades deportivas.',NULL,0,'Aragón','2026-07-27 00:00:00','revisada',0,NULL,NULL,'127.0.0.1'),(42677,'Ciudadano 7','sug7@example.com','25','empleo','alta','Mentoría laboral','Conectar jóvenes con profesionales.',NULL,1,'Aragón','2026-07-26 00:00:00','en_progreso',0,NULL,NULL,'127.0.0.1'),(42678,'Ciudadano 8','sug8@example.com','26','ocio','baja','Parque de skate','Nueva pista de skate en el centro.',NULL,0,'Aragón','2026-07-25 00:00:00','resuelta',0,NULL,NULL,'127.0.0.1'),(42679,'Ciudadano 9','sug9@example.com','27','transporte','alta','Transporte sostenible','Bonos de bici compartida.',NULL,1,'Aragón','2026-07-24 00:00:00','rechazada',0,NULL,NULL,'127.0.0.1');
